import React from 'react';
import moment from 'moment';
import { Link } from 'gatsby';
import type { Edges } from '../../types';
import styles from './Feed.module.scss';

type Props = {
  edges: Edges
};

const Feed = ({ edges }: Props) => (
  <ul className={styles['feed']}>
    {edges.map(({ node }) => (
      <li className={styles['feed__item']} key={node.fields.slug}>
        <article>
          <p className={styles['feed__item-meta']}>
            <time dateTime={moment(node.frontmatter.date).format('YYYY-MM-DD')}>
              {moment(node.frontmatter.date).format('MMM D, YYYY')}
            </time>
          </p>
          <h2 className={styles['feed__item-title']}>
            <Link className={styles['feed__item-title-link']} to={node.fields.slug}>{node.frontmatter.title}</Link>
          </h2>
          {node.frontmatter.description && (
            <p className={styles['feed__item-description']}>{node.frontmatter.description}</p>
          )}
        </article>
      </li>
    ))}
  </ul>
);

export default Feed;
