import React from 'react';
import { Link } from 'gatsby';
import { PAGINATION } from '../../constants';
import styles from './Pagination.module.scss';

type Props = {
  prevPagePath: string,
  nextPagePath: string,
  hasNextPage: boolean,
  hasPrevPage: boolean
};

const Pagination = ({
  prevPagePath,
  nextPagePath,
  hasNextPage,
  hasPrevPage
}: Props) => {
  if (!hasPrevPage && !hasNextPage) {
    return null;
  }

  return (
    <nav className={styles['pagination']} aria-label="Pagination">
      <div>
        {hasPrevPage && <Link rel="prev" to={prevPagePath} className={styles['pagination__link']}>{PAGINATION.PREV_PAGE}</Link>}
      </div>
      <div>
        {hasNextPage && <Link rel="next" to={nextPagePath} className={styles['pagination__link']}>{PAGINATION.NEXT_PAGE}</Link>}
      </div>
    </nav>
  );
};

export default Pagination;
